plugins {
	alias(libs.plugins.aboutlibraries)
	alias(libs.plugins.android.application)
	// Velella: baseline profile, generated by :baselineprofile
	alias(libs.plugins.androidx.baselineprofile)
	alias(libs.plugins.kotlin.compose)
	alias(libs.plugins.kotlin.serialization)
}

// Velella: own application id, so it installs next to the official app. The namespace stays unchanged.
val velellaAppId = "com.velella.app"

android {
	namespace = "org.jellyfin.androidtv"
	compileSdk = libs.versions.android.compileSdk.get().toInt()

	defaultConfig {
		minSdk = libs.versions.android.minSdk.get().toInt()
		targetSdk = libs.versions.android.targetSdk.get().toInt()

		// Release version
		applicationId = velellaAppId
		versionName = project.getVersionName()
		versionCode = getVersionCode(versionName!!)
	}

	// Velella: drop files the app never reads at runtime
	packaging {
		resources.excludes += listOf(
			"DebugProbesKt.bin",
			"kotlin-tooling-metadata.json",
			"META-INF/*.version",
		)
	}

	buildFeatures {
		buildConfig = true
		viewBinding = true
		compose = true
		resValues = true
	}

	compileOptions {
		isCoreLibraryDesugaringEnabled = true
	}

	signingConfigs {
		val signingProperties = listOfNotNull(
			getProperty("keystore.file"),
			getProperty("keystore.password"),
			getProperty("signing.key.alias"),
			getProperty("signing.key.password"),
		)

		val signingPropertyCount = 4

		// Only create the release config when all four properties are set
		if (signingProperties.size == signingPropertyCount) {
			create("release") {
				storeFile = file(signingProperties[0])
				storePassword = signingProperties[1]
				keyAlias = signingProperties[2]
				keyPassword = signingProperties[3]
			}
		}
	}

	dependenciesInfo {
		includeInBundle = false
		includeInApk = false
	}

	buildTypes {
		release {
			isMinifyEnabled = true
			isShrinkResources = true
			proguardFiles(getDefaultProguardFile("proguard-android-optimize.txt"), "proguard-rules.pro")

			// Velella: Shield TV 2015, 2017 and 2019 Pro run a 64-bit userspace, the 2019 tube a 32-bit one; x86 ABIs only add
			// native weight (FFmpeg, libass). Debug builds keep every ABI so they still install on x86 emulators.
			ndk { abiFilters += listOf("arm64-v8a", "armeabi-v7a") }

			// Set package names used in various XML files
			resValue("string", "app_id", velellaAppId)
			resValue("string", "app_search_suggest_authority", "${velellaAppId}.content")
			resValue("string", "app_search_suggest_intent_data", "content://${velellaAppId}.content/intent")

			// Set flavored application name
			resValue("string", "app_name", "@string/velella_app_name")

			buildConfigField("boolean", "DEVELOPMENT", "false")

			signingConfig = signingConfigs.findByName("release")
		}

		debug {
			// Use different application id to run release and debug at the same time
			applicationIdSuffix = ".debug"

			// Set package names used in various XML files
			resValue("string", "app_id", velellaAppId + applicationIdSuffix)
			resValue("string", "app_search_suggest_authority", "${velellaAppId + applicationIdSuffix}.content")
			resValue("string", "app_search_suggest_intent_data", "content://${velellaAppId + applicationIdSuffix}.content/intent")

			// Set flavored application name
			resValue("string", "app_name", "@string/velella_app_name_debug")

			buildConfigField("boolean", "DEVELOPMENT", (defaultConfig.versionCode!! < 100).toString())
		}
	}

	lint {
		lintConfig = file("$rootDir/config/android-lint.xml")
		abortOnError = false
		checkDependencies = true
	}

	testOptions.unitTests.all {
		it.useJUnitPlatform()
	}
}

base.archivesName.set("velella-v${project.getVersionName()}")

// Velella: native libraries bundled inside other packages (FFmpeg, libass and its font stack), listed in the licenses screen
aboutLibraries {
	collect {
		configPath = file("config/aboutlibraries")
	}
	library {
		// Its POM says GPL-3.0 (the packaging repository's licence); config/aboutlibraries lists it with the shipped code's licences
		exclusionPatterns.add(Regex("org\\.jellyfin\\.media3:media3-ffmpeg-decoder").toPattern())
	}
}

tasks.register("versionTxt") {
	val path = layout.buildDirectory.asFile.get().resolve("version.txt")

	doLast {
		val versionString = "v${android.defaultConfig.versionName}=${android.defaultConfig.versionCode}"
		logger.info("Writing [$versionString] to $path")
		path.writeText("$versionString\n")
	}
}

dependencies {
	// Jellyfin
	implementation(projects.design)
	implementation(projects.playback.core)
	implementation(projects.playback.jellyfin)
	implementation(projects.playback.media3.exoplayer)
	implementation(projects.playback.media3.session)
	implementation(projects.preference)
	implementation(libs.jellyfin.sdk) {
		// Change version if desired
		val sdkVersion = findProperty("sdk.version")?.toString()
		when (sdkVersion) {
			"local" -> version { strictly("latest-SNAPSHOT") }
			"snapshot" -> version { strictly("master-SNAPSHOT") }
			"unstable-snapshot" -> version { strictly("openapi-unstable-SNAPSHOT") }
		}
	}

	// Kotlin
	implementation(libs.kotlinx.coroutines)
	implementation(libs.kotlinx.serialization.json)

	// Android(x)
	implementation(libs.androidx.core)
	implementation(libs.androidx.activity)
	implementation(libs.androidx.activity.compose)
	implementation(libs.androidx.fragment)
	implementation(libs.androidx.fragment.compose)
	implementation(libs.androidx.leanback.core)
	implementation(libs.androidx.leanback.preference)
	implementation(libs.androidx.navigation3.ui)
	implementation(libs.androidx.preference)
	implementation(libs.androidx.appcompat)
	implementation(libs.androidx.tvprovider)
	implementation(libs.androidx.constraintlayout)
	implementation(libs.androidx.recyclerview)
	implementation(libs.androidx.work.runtime)
	implementation(libs.bundles.androidx.lifecycle)
	implementation(libs.androidx.window)
	implementation(libs.androidx.cardview)
	implementation(libs.androidx.startup)
	implementation(libs.bundles.androidx.compose)

	// Dependency Injection
	implementation(libs.bundles.koin)

	// Media players
	implementation(libs.androidx.media3.exoplayer)
	implementation(libs.androidx.media3.datasource.okhttp)
	implementation(libs.androidx.media3.exoplayer.hls)
	implementation(libs.androidx.media3.ui)
	implementation(libs.jellyfin.androidx.media3.ffmpeg.decoder)
	implementation(libs.libass.media3)

	// Markdown
	implementation(libs.bundles.markwon)

	// Image utility
	implementation(libs.bundles.coil)

	// Crash Reporting
	implementation(libs.bundles.acra)

	// Licenses
	implementation(libs.aboutlibraries)

	// Logging
	implementation(libs.timber)
	implementation(libs.slf4j.timber)

	// Compatibility (desugaring)
	coreLibraryDesugaring(libs.android.desugar)

	// Velella: baseline profile, installed by profileinstaller even when the APK is sideloaded
	implementation(libs.androidx.profileinstaller)
	baselineProfile(projects.baselineprofile)

	// Testing
	testImplementation(libs.kotest.runner.junit5)
	testImplementation(libs.kotest.assertions)
	testImplementation(libs.mockk)
}

// Velella: fail the build if a Google service SDK reaches the app (buildSrc/src/main/kotlin/GoogleServicesGuard.kt)
verifyNoGoogleServices()
